public IEShaderLayerCompositeTexture(ResourceLocation canvasTexture, ShaderLayer[] layers)
	{
		this.canvasTexture = canvasTexture;
		this.layers = layers;
	}

private ColorABGR(float a, float b, float g, float r)
		{
			this.a = Math.clamp(a, 0, 1);
			this.b = Math.clamp(b, 0, 1);
			this.g = Math.clamp(g, 0, 1);
			this.r = Math.clamp(r, 0, 1);
		}

public ColorABGR(int abgr)
		{
			this((abgr>>24&255)/255f, (abgr>>16&255)/255f, (abgr>>8&255)/255f, (abgr&255)/255f);
		}

public static ColorABGR blend(ColorABGR input, ColorABGR existing)
		{
			float mixFactor = 1.0F-input.a;
			float newAlpha = input.a*input.a+existing.a*mixFactor;
			if(existing.a==0)
				newAlpha = input.a;
			else if(newAlpha < existing.a)
				newAlpha = existing.a;
			return new ColorABGR(
					newAlpha,
					input.b*input.a+existing.b*mixFactor,
					input.g*input.a+existing.g*mixFactor,
					input.r*input.a+existing.r*mixFactor
			);
		}

public boolean isTransparent()
		{
			return a==0||(r==0&&g==0&&b==0);
		}

public void modify(float[] rgba)
		{
			this.a *= rgba[0];
			this.b *= rgba[1];
			this.g *= rgba[2];
			this.r *= rgba[3];
		}

public int toInt()
		{
			return (int)(a*255)<<24|(int)(b*255)<<16|(int)(g*255)<<8|(int)(r*255);
		}

public ShaderBannerRenderer(BlockEntityRendererProvider.Context ctx)
	{
		ModelPart modelpart = ctx.bakeLayer(ModelLayers.BANNER);
		this.clothModel = modelpart.getChild("flag");
		this.standingModel = modelpart.getChild("pole");
		this.crossbar = modelpart.getChild("bar");
	}

@Override
	public void render(ShaderBannerBlockEntity te, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		long time = te.getLevelNonnull().getGameTime();
		matrixStack.pushPose();

		// Check which of the two blocks we are so we can calculate the orientation.
		if(te.getState().getBlock()==Cloth.SHADER_BANNER.get())
		{
			// Standing banner, we have 16 different rotations.
			int orientation = te.getState().getValue(ShaderBannerStandingBlock.ROTATION);
			matrixStack.translate(0.5F, 0.5F, 0.5F);
			float f1 = (float)(orientation*360)/16.0F;
			matrixStack.mulPose(new Quaternionf().rotateY(-f1 * Mth.DEG_TO_RAD));
			standingModel.visible = true;
		}
		else
		{
			// Must be the wall banner, attaches to the side of the block with no support pillar.
			assert te.getState().getBlock()==Cloth.SHADER_BANNER_WALL.get();

			Direction facing = te.getState().getValue(ShaderBannerWallBlock.FACING);
			float rotation = facing.toYRot();

			matrixStack.translate(0.5F, -1/6f, 0.5F);
			matrixStack.mulPose(new Quaternionf().rotateY(-rotation * Mth.DEG_TO_RAD));
			matrixStack.translate(0.0F, -0.3125F, -0.4375F);
			standingModel.visible = false;
		}

		BlockPos blockpos = te.getBlockPos();
		float f3 = (float)(blockpos.getX()*7+blockpos.getY()*9+blockpos.getZ()*13)+(float)time+partialTicks;
		clothModel.xRot = (-0.0125F+0.01F*Mth.cos(f3*(float)Math.PI*0.02F))*(float)Math.PI;
		clothModel.y = -32.0F;
		ResourceLocation resourcelocation = this.getBannerResourceLocation(te);

		if(resourcelocation!=null)
		{
			matrixStack.pushPose();

			matrixStack.scale(2f/3, -2f/3, -2f/3);
			VertexConsumer builder;
			builder = bufferIn.getBuffer(RenderType.entitySolid(resourcelocation));
			this.clothModel.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);
			builder = ModelBakery.BANNER_BASE.buffer(bufferIn, RenderType::entitySolid);
			this.crossbar.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);
			this.standingModel.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);

			matrixStack.popPose();
		}

		matrixStack.popPose();
	}

@Nullable
	private ResourceLocation getBannerResourceLocation(ShaderBannerBlockEntity bannerObj)
	{
		return getShaderResourceLocation(bannerObj.shader.getShader(), bannerObj.shader.getShaderType());
	}

@Nullable
	public static ResourceLocation getShaderResourceLocation(ResourceLocation shader, ResourceLocation shaderType)
	{
		ShaderCase sCase = ShaderRegistry.getShader(shader, shaderType);

		if(sCase!=null)
		{
			ShaderLayer[] layers = sCase.getLayers();
			ResourceLocation textureLocation = shader.withPath("bannershader/"+shader.getPath());
			ClientUtils.mc().getTextureManager().register(textureLocation, new IEShaderLayerCompositeTexture(BASE_TEXTURE, layers));
			CACHE.put(shader, textureLocation);
			return textureLocation;
		}
		return null;
	}

@Override
	public ResourceLocation getShaderName()
	{
		return this.shaderName;
	}

@Nonnull
	@Override
	public InteractionResult useOn(UseOnContext ctx)
	{
		Level world = ctx.getLevel();
		BlockPos pos = ctx.getClickedPos();
		ResourceLocation name = getShaderName();
		if(ShaderRegistry.shaderRegistry.containsKey(name))
		{
			BlockState blockState = world.getBlockState(pos);
			BlockEntity tile = world.getBlockEntity(pos);
			if(tile instanceof BannerBlockEntity)
			{
				ShaderCase sCase = ShaderRegistry.shaderRegistry.get(name).getCase(IEApi.ieLoc("banner"));
				if(sCase!=null)
				{
					boolean wall = blockState.getBlock() instanceof WallBannerBlock;

					if(wall)
						world.setBlockAndUpdate(pos, Cloth.SHADER_BANNER_WALL.defaultBlockState()
								.setValue(ShaderBannerWallBlock.FACING, blockState.getValue(WallBannerBlock.FACING)));
					else
						world.setBlockAndUpdate(pos, Cloth.SHADER_BANNER.defaultBlockState()
								.setValue(ShaderBannerStandingBlock.ROTATION, blockState.getValue(BannerBlock.ROTATION)));
					tile = world.getBlockEntity(pos);
					if(tile instanceof ShaderBannerBlockEntity shaderBanner)
					{
						shaderBanner.shader.setShader(shaderName);
						tile.setChanged();
						return InteractionResult.SUCCESS;
					}
				}
			}
			else if(tile instanceof ShaderBannerBlockEntity shaderBanner)
			{
				shaderBanner.shader.setShader(shaderName);
				tile.setChanged();
				return InteractionResult.SUCCESS;
			}

		}
		return InteractionResult.FAIL;
	}

@Override
